  'Длительность: часы и минуты': { en: 'Duration: hours and minutes', de: 'Dauer: Stunden und Minuten', uk: 'Тривалість: години та хвилини', es: 'Duración: horas y minutos' },
  'Часы': { en: 'Hours', de: 'Stunden', uk: 'Години', es: 'Horas' },
