function programSkillMap(prog, existingSkills) {
  const map = {}, skills = (existingSkills || []).slice();
  skills.forEach((sk) => { map[sk.name.toLowerCase()] = sk.id; });
  prog.skills.forEach((ps) => {
    const k = ps.name.toLowerCase();
    if (!map[k]) { const id = 'sk_' + k.replace(/[^a-z0-9]/g, '') + '_' + Math.random().toString(36).slice(2, 7); skills.push({ id, name: ps.name, color: ps.color }); map[k] = id; }
  });
  // Второй проход: связываем под-сферы с родителем по имени (пресеты с иерархией, напр. Здоровье ⊃ Спорт/Сон)
  prog.skills.forEach((ps) => {
    if (!ps.parent) return;
    const sk = skills.find((s) => s.id === map[ps.name.toLowerCase()]), pid = map[ps.parent.toLowerCase()];
    if (sk && pid && sk.id !== pid) sk.parentId = pid;
  });
  return { skills, map };
}
function programHabits(prog, map) { return (prog.habits || []).map((ph) => ({ id: 'h_' + uid(), title: ph.title, skillId: map[ph.skill.toLowerCase()], difficulty: ph.difficulty || 'normal', estimateMin: ph.estimateMin || 10, days: ph.days || [1, 2, 3, 4, 5], archived: false, createdAt: new Date().toISOString() })); }
function programTasks(prog, map) { return (prog.quests || []).map((pq) => ({ id: uid(), title: pq.title, skillId: map[pq.skill.toLowerCase()], estimateMin: pq.estimateMin || 20, difficulty: pq.difficulty || 'normal', date: todayStr(), done: false, completedAt: null, xpAwarded: 0, goldAwarded: 0, actualMin: null, startTime: null, createdAt: new Date().toISOString() })); }

// Онбординг: чистый профиль из программы. Пишем файлы НАПРЯМУЮ (await), чтобы initApp их загрузил без гонки.
async function applyProgramFresh(prog) {
  if (State._onboardingSaveBusy) return;
  const { skills, map } = programSkillMap(prog, []);
  const settings = freshOnboardingSettings(skills);
  // Публичный X7 — отдельный showcase-профиль на каждый браузер. Даём ему достаточно
  // импортированного опыта, чтобы ревьюер мог открыть все разделы, но исключаем из
  // лидерборда: демонстрационный прогресс не должен соревноваться с живыми игроками.
  if (demoX7Requested()) {
    const anchor = skills[0];
    settings.imported = anchor ? {
      [anchor.id]: { tier: 5, xp: 6700, label: 'X7 showcase', at: new Date().toISOString() },
    } : {};
    settings.social = { leaderboard: false, party: false };
    settings.demoMode = 'x7';
    settings.tutorial = { i: 0, active: false, done: false, skipped: true, seenDrips: [], mode: 'day1', dripId: null };
    if (window.GuideV3) settings.guideV3 = Object.assign(window.GuideV3.defaultState(), { enabled: false });
  }
  const result = await onboardingSave([
    ['settings', settings], ['habits', programHabits(prog, map)], ['tasks', programTasks(prog, map)],
  ]);
  if (!result.ok) return;
  State.phase = 'app'; initApp();
}
async function loginAsTestUser() {
  const btn = document.querySelector('[data-action="test-login"]');
  if (btn) { btn.disabled = true; btn.textContent = t('🧪 Входим...'); }
  const testUser = demoX7Requested() ? demoX7Identity() : TEST_USER;
  const payload = { email: testUser.email, password: testUser.password };
  try {
    let r = await fetch('/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    let d = await r.json();
    if (r.ok) {
      State.me = d;
      initApp();
      return;
    }

    r = await fetch('/api/auth/register', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(testUser),
    });
    d = await r.json();
    if (!r.ok) throw new Error(d.error ? t(d.error) : t('Не удалось создать тестового пользователя'));

    State.me = d;
    const prog = DUNGEON_PROGRAMS.find((x) => x.id === 'decathlete') || DUNGEON_PROGRAMS[0];
    if (prog) await applyProgramFresh(prog);
    else { State.phase = 'onboarding'; render(); }
  } catch (err) {
    const box = document.getElementById('login-error');
    if (box) box.textContent = err.message || t('Ошибка тестового входа');
    if (btn) { btn.disabled = false; btn.textContent = t('🧪 Войти как тестовый пользователь'); }
  }
}
// В приложении: домерживаем программу к существующим данным (не затирая их).
function applyProgramMerge(prog) {
  const { skills, map } = programSkillMap(prog, State.settings.skills);
  State.settings.skills = skills;
  State.habits.push(...programHabits(prog, map));
  State.tasks.push(...programTasks(prog, map));
  Store.save('settings', State.settings); Store.save('habits', State.habits); Store.save('tasks', State.tasks);
  toast(`📦 ${t('Программа добавлена')}: ${prog.name}`); render();
}
function programCard(p, action) {
  // aria-label: внутри кнопки только спаны — без него скринридер видит безымянную кнопку (a11y-находка альфа-аудита)
  return `<button type="button" class="prog-card" data-action="${action}" data-prog="${p.id}" aria-label="${esc(t('Программа'))}: ${esc(p.name)} — ${esc(p.tagline)}">
    <span class="pc-ic">${p.icon}</span>
    <span class="pc-body">
      <span class="pc-name">${esc(p.name)}</span>
      <span class="pc-tag">${esc(p.tagline)}</span>
      <span class="pc-meta">${p.skills.map((s) => esc(s.name)).join(' · ')} · ${(p.habits || []).length} прив. · ${(p.quests || []).length} квест.</span>
    </span></button>`;
}

