function syncDenLife() {
  if (!window.DenLifeV1) return false;
  if (State.view !== 'den') {
    if (window.DenPetPairV1) window.DenPetPairV1.stop();
    return window.DenLifeV1.stop();
  }
  const shell = document.querySelector('.den-shell');
  const sphereId = bodyGuardianSphereId();
  const resourcesSphereId = resourcesGuardianSphereId();
  const hasBodyGuardian = Boolean(shell && sphereId && shell.querySelector('[data-body-toad]'));
  const hasRecoveryGuardian = Boolean(shell && shell.querySelector('[data-recovery-slug]'));
  const hasResourcesGuardian = Boolean(shell && resourcesSphereId && shell.querySelector('[data-resources-penguin]'));
  const hasShadow = Boolean(shell && shell.querySelector('[data-shadow-den]') && window.ShadowDenV1);
  if (!shell || (!hasBodyGuardian && !hasRecoveryGuardian && !hasResourcesGuardian && !hasShadow)) {
    if (window.DenPetPairV1) window.DenPetPairV1.stop();
    return window.DenLifeV1.stop();
  }
  const started = window.DenLifeV1.start(shell, {
    context: denLifeContext(),
    canAct: () => denLifeCanAct(shell),
    onPair: (mode, options) => hasBodyGuardian ? playBodyToadScene(shell, sphereId, mode, options) : false,
    onRecoveryBeat: (beatId) => hasRecoveryGuardian ? playDenRecoveryBeat(shell, beatId) : false,
    onResourcesBeat: (beatId) => hasResourcesGuardian ? playDenResourcesBeat(shell, resourcesSphereId, beatId) : false,
    onResourcesPair: (mode, options) => hasResourcesGuardian ? playResourcesPenguinScene(shell, resourcesSphereId, mode, options) : false,
    onShadowBeat: (beatId) => hasShadow ? playDenShadowBeat(shell, beatId) : false,
    onShadowPair: (mode, options) => hasShadow ? playShadowPairScene(shell, mode, options) : false,
    onRoomAction: (actionId) => runDenRoomAction(actionId, { automatic: true, waitForFinish: true }),
    onWindowVisit: () => runDenAvatarWindowVisit({ automatic: true, reschedule: false }),
    onToadBeat: (beatId) => playDenToadBeat(shell, sphereId, beatId),
  });
  if (window.DenPetPairV1) {
    window.DenPetPairV1.start(shell, {
      ready: () => Number(window.DenLifeV1.inspect()?.step || 0) >= 4,
      canAct: () => denLifeCanAct(shell),
      context: () => ({
        dayLoad: dayLoadNow().state,
        focusCanon: denLifeContext().focusCanon,
        residents: [hasBodyGuardian && 'body', hasRecoveryGuardian && 'recovery', hasResourcesGuardian && 'resources', hasShadow && 'shadow'].filter(Boolean),
        returning: false,
      }),
      onScene: (sceneId, options) => playPetPairScene(shell, sceneId, options),
    });
  }
  return started;
}

let _denViewportObserver = null;
function pauseDenSceneForViewport(shell) {
  if (!shell || !shell.isConnected) return;
  shell.classList.add('is-den-offscreen');
  abortDenSceneAction(shell, 'offscreen').catch(() => {});
}
function syncDenViewportGate() {
  if (_denViewportObserver) {
    _denViewportObserver.disconnect();
    _denViewportObserver = null;
  }
  const shell = State.view === 'den' ? document.querySelector('.den-shell') : null;
  const scene = shell && shell.querySelector('.den-scene');
  if (!shell || !scene || typeof IntersectionObserver === 'undefined') return;
  _denViewportObserver = new IntersectionObserver((entries) => {
    const entry = entries[0];
    if (!entry || !shell.isConnected) return;
    const offscreen = !entry.isIntersecting;
    shell.classList.toggle('is-den-offscreen', offscreen);
    if (offscreen) {
      pauseDenSceneForViewport(shell);
    } else {
      syncAvatarMotion();
    }
  }, { threshold: 0.01 });
  _denViewportObserver.observe(scene);
}

function openAvatarForgeEditor() {
  const existing = document.getElementById('avatar-forge-overlay');
  if (existing) {
    existing.querySelector('iframe')?.focus();
    return;
  }
  const overlay = document.createElement('div');
  overlay.id = 'avatar-forge-overlay';
  overlay.className = 'avatar-forge-overlay';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-label', 'Редактор внешности');
  overlay.innerHTML = '<iframe id="avatar-forge-frame" src="/avatar-forge-v1.html?embedded=1&build=20260801-colorways-v1" title="Avatar Forge" allow="none"></iframe>';
  document.body.appendChild(overlay);
  document.documentElement.classList.add('avatar-forge-open');
  requestAnimationFrame(() => overlay.classList.add('is-visible'));
}
function closeAvatarForgeEditor() {
  const overlay = document.getElementById('avatar-forge-overlay');
  if (!overlay) return;
  overlay.classList.remove('is-visible');
  document.documentElement.classList.remove('avatar-forge-open');
  setTimeout(() => overlay.remove(), 160);
}
async function onAvatarForgeMessage(event) {
  const frame = document.getElementById('avatar-forge-frame');
  if (!frame || event.origin !== location.origin || event.source !== frame.contentWindow || !isPlainRecord(event.data)) return;
  const message = event.data;
  if (message.source !== 'satoru-avatar-forge' || message.messageVersion !== AVATAR_FORGE_MESSAGE_VERSION) return;
  if (message.type === 'ready') {
    frame.contentWindow.postMessage({
      source: 'satoru-app',
      messageVersion: AVATAR_FORGE_MESSAGE_VERSION,
      type: 'init',
      appearance: avatarAppearance(),
    }, location.origin);
    return;
  }
  if (message.type === 'close') {
    closeAvatarForgeEditor();
    return;
  }
  if (message.type !== 'apply') return;
  const next = validateAvatarForgeAppearance(message.appearance);
  if (!next) {
    toast(t('Редактор вернул неверную схему образа'));
    return;
  }
  const overlay = document.getElementById('avatar-forge-overlay');
  if (overlay?.classList.contains('is-applying')) return;
  overlay?.classList.add('is-applying');
  try {
    await queueAvatarAppearanceRender(next);
    closeAvatarForgeEditor();
    toast(t('Образ сохранён'));
  } catch {
    overlay?.classList.remove('is-applying');
  }
}
if (typeof window !== 'undefined') {
  window.triggerAvatarReaction = triggerAvatarReaction;
  window.addEventListener('message', onAvatarForgeMessage);
}
function shade(hex, amt) { // amt -100..100 (минус = темнее)
  const n = parseInt(hex.slice(1), 16); let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  const t = amt < 0 ? 0 : 255, p = Math.abs(amt) / 100;
  r = Math.round((t - r) * p + r); g = Math.round((t - g) * p + g); b = Math.round((t - b) * p + b);
  return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}
function avatarSVG(cfg, opts = {}) {
  cfg = Object.assign(defaultAvatar(), cfg);
  const skin = AV_SKINS[cfg.skin] || AV_SKINS[1];
  const sd = shade(skin, -14), hair = AV_HAIRC[cfg.hairColor] || AV_HAIRC[1];
  const cloth = AV_CLOTH[cfg.cloth] || AV_CLOTH[0];
  const cx = 120;
  const faces = [{ rx: 56, ry: 62, cy: 116 }, { rx: 50, ry: 65, cy: 118 }, { rx: 60, ry: 57, cy: 114 }];
  const F = faces[cfg.face] || faces[0], cy = F.cy, rx = F.rx, ry = F.ry;
  const eyeY = cy + 2, eyeDX = rx * 0.44, browY = eyeY - 15, mouthY = cy + ry * 0.52;
  // ---- части ----
  const ear = `<ellipse cx="${cx - rx + 3}" cy="${cy + 8}" rx="9" ry="12" fill="${skin}"/><ellipse cx="${cx + rx - 3}" cy="${cy + 8}" rx="9" ry="12" fill="${skin}"/>`;
  const neck = `<path d="M${cx - 15} ${cy + ry - 14} h30 v22 q0 8 -15 8 q-15 0 -15 -8 z" fill="${sd}"/>`;
  const shoulders = `<path d="M${cx - 78} 240 Q ${cx - 70} 184 ${cx} 182 Q ${cx + 70} 184 ${cx + 78} 240 Z" fill="${cloth}"/><path d="M${cx - 16} 184 Q ${cx} 200 ${cx + 16} 184 L ${cx + 16} 196 Q ${cx} 206 ${cx - 16} 196 Z" fill="${shade(cloth, -16)}"/>`;
  const head = `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${skin}"/>`;
  // глаза
  const eye = (ex) => {
    const E = cfg.eyes;
    if (E === 1) return `<path d="M${ex - 8} ${eyeY} Q ${ex} ${eyeY - 6} ${ex + 8} ${eyeY} Q ${ex} ${eyeY + 5} ${ex - 8} ${eyeY} Z" fill="#fff"/><circle cx="${ex}" cy="${eyeY}" r="4" fill="#3a2a20"/>`;
    if (E === 2) return `<circle cx="${ex}" cy="${eyeY}" r="8" fill="#fff"/><circle cx="${ex}" cy="${eyeY}" r="5.5" fill="#3a2a20"/><circle cx="${ex + 2}" cy="${eyeY - 2}" r="1.6" fill="#fff"/>`;
    if (E === 3) return `<path d="M${ex - 8} ${eyeY} q 8 7 16 0" stroke="#3a2a20" stroke-width="3" fill="none" stroke-linecap="round"/>`;
    return `<ellipse cx="${ex}" cy="${eyeY}" rx="6.5" ry="7.5" fill="#fff"/><circle cx="${ex}" cy="${eyeY + 0.5}" r="4" fill="#3a2a20"/><circle cx="${ex + 1.5}" cy="${eyeY - 1.5}" r="1.4" fill="#fff"/>`;
  };
  const eyes = eye(cx - eyeDX) + eye(cx + eyeDX);
  // брови
  const brow = (bx, dir) => {
    const B = cfg.brows;
    if (B === 1) return `<path d="M${bx - 9} ${browY + 2} Q ${bx} ${browY - 4} ${bx + 9} ${browY + 2}" stroke="${shade(hair, -10)}" stroke-width="3.5" fill="none" stroke-linecap="round"/>`;
    if (B === 2) return `<rect x="${bx - 9}" y="${browY - 2}" width="18" height="4.5" rx="2.2" fill="${shade(hair, -10)}"/>`;
    return `<path d="M${bx - 9} ${browY} L ${bx + 9} ${browY - (dir * 2)}" stroke="${shade(hair, -10)}" stroke-width="3.2" fill="none" stroke-linecap="round"/>`;
  };
  const brows = brow(cx - eyeDX, 1) + brow(cx + eyeDX, -1);
  // нос
  const nose = `<path d="M${cx} ${cy + 4} q -4 12 -1 15 q 2 1.5 5 0.5" stroke="${sd}" stroke-width="2.4" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`;
  // рот
  let mouth;
  if (cfg.mouth === 1) mouth = `<line x1="${cx - 12}" y1="${mouthY}" x2="${cx + 12}" y2="${mouthY}" stroke="#9c5247" stroke-width="3" stroke-linecap="round"/>`;
  else if (cfg.mouth === 2) mouth = `<path d="M${cx - 15} ${mouthY - 2} Q ${cx} ${mouthY + 14} ${cx + 15} ${mouthY - 2} Z" fill="#8e4038"/><path d="M${cx - 12} ${mouthY} Q ${cx} ${mouthY + 4} ${cx + 12} ${mouthY}" fill="#fff"/>`;
  else if (cfg.mouth === 3) mouth = `<path d="M${cx - 9} ${mouthY} Q ${cx} ${mouthY + 7} ${cx + 9} ${mouthY}" stroke="#9c5247" stroke-width="3" fill="none" stroke-linecap="round"/>`;
  else mouth = `<path d="M${cx - 15} ${mouthY - 1} Q ${cx} ${mouthY + 13} ${cx + 15} ${mouthY - 1}" stroke="#9c5247" stroke-width="3.2" fill="none" stroke-linecap="round"/>`;
  // борода
  let beard = '';
  if (cfg.beard === 1) beard = `<path d="M${cx - rx + 4} ${cy} Q ${cx - rx} ${cy + ry} ${cx} ${cy + ry + 1} Q ${cx + rx} ${cy + ry} ${cx + rx - 4} ${cy} Q ${cx} ${cy + ry * 0.5} ${cx - rx + 4} ${cy} Z" fill="${hair}" opacity="0.32"/>`;
  else if (cfg.beard === 2) beard = `<path d="M${cx - rx + 2} ${cy - 4} Q ${cx - rx} ${cy + ry + 4} ${cx} ${cy + ry + 6} Q ${cx + rx} ${cy + ry + 4} ${cx + rx - 2} ${cy - 4} Q ${cx} ${cy + ry * 0.62} ${cx - rx + 2} ${cy - 4} Z" fill="${hair}"/>`;
  // волосы (back + front)
  const hairParts = avHair(cfg.hair, cx, cy, rx, ry, hair);
  // очки
  let glasses = '';
  if (cfg.glasses) {
    const lens = cfg.glasses === 1
      ? `<circle cx="${cx - eyeDX}" cy="${eyeY}" r="11" fill="none" stroke="#2a3250" stroke-width="2.6"/><circle cx="${cx + eyeDX}" cy="${eyeY}" r="11" fill="none" stroke="#2a3250" stroke-width="2.6"/>`
      : `<rect x="${cx - eyeDX - 11}" y="${eyeY - 9}" width="22" height="18" rx="4" fill="none" stroke="#2a3250" stroke-width="2.6"/><rect x="${cx + eyeDX - 11}" y="${eyeY - 9}" width="22" height="18" rx="4" fill="none" stroke="#2a3250" stroke-width="2.6"/>`;
    glasses = lens + `<line x1="${cx - eyeDX + 11}" y1="${eyeY}" x2="${cx + eyeDX - 11}" y2="${eyeY}" stroke="#2a3250" stroke-width="2.6"/>`;
  }
  const bg = opts.bg ? `<rect x="0" y="0" width="240" height="240" fill="${opts.bg}"/>` : '';
  // косметическая рамка (кольцо по краю) — дроп из сундуков
  const fr = opts.frame ? `${opts.frame.glow ? `<circle cx="120" cy="120" r="111" fill="none" stroke="${opts.frame.ring}" stroke-width="3" opacity="0.5"/>` : ''}<circle cx="120" cy="120" r="117" fill="none" stroke="${opts.frame.ring}" stroke-width="6"/>` : '';
  return `<svg viewBox="0 0 240 240" class="avatar-svg" preserveAspectRatio="xMidYMid slice">${bg}${hairParts.back}${shoulders}${neck}${ear}${head}${beard}${hairParts.front}${brows}${eyes}${nose}${mouth}${glasses}${fr}</svg>`;
}
function avHair(style, cx, cy, rx, ry, hair) {
  if (!style) return { back: '', front: '' };
  const topY = cy - ry, R = rx * 1.06;
  // базовая «шапка»: дуга поверх головы + линия волос
  const cap = (lineY, extra = '') => `<path d="M${cx - R} ${cy - ry * 0.1} A ${R} ${ry * 1.05} 0 0 1 ${cx + R} ${cy - ry * 0.1} Q ${cx + rx * 0.55} ${lineY} ${cx} ${lineY + 2} Q ${cx - rx * 0.55} ${lineY} ${cx - R} ${cy - ry * 0.1} Z" fill="${hair}"/>${extra}`;
  switch (style) {
    case 1: // короткая
      return { back: '', front: cap(cy - ry * 0.42) };
    case 2: // ёжик/buzz
      return { back: '', front: cap(cy - ry * 0.58) };
    case 3: { // квифф (зачёс наверх)
      const tuft = `<path d="M${cx - 6} ${topY + 4} Q ${cx + 4} ${topY - 18} ${cx + 22} ${topY + 2} Q ${cx + 6} ${topY + 2} ${cx - 6} ${topY + 4} Z" fill="${hair}"/>`;
      return { back: '', front: cap(cy - ry * 0.4, tuft) };
    }
    case 4: { // длинные
      const back = `<path d="M${cx - rx - 6} ${cy - ry * 0.2} Q ${cx - rx - 14} ${cy + ry + 30} ${cx - rx + 8} ${cy + ry + 36} L ${cx + rx - 8} ${cy + ry + 36} Q ${cx + rx + 14} ${cy + ry + 30} ${cx + rx + 6} ${cy - ry * 0.2} Z" fill="${hair}"/>`;
      return { back, front: cap(cy - ry * 0.3) };
    }
    case 5: { // пучок
      const bun = `<circle cx="${cx}" cy="${topY - 6}" r="16" fill="${hair}"/>`;
      return { back: bun, front: cap(cy - ry * 0.48) };
    }
    case 6: { // кудри
      let curls = '';
      for (let i = -3; i <= 3; i++) curls += `<circle cx="${cx + i * (rx / 3.2)}" cy="${cy - ry * 0.78 + Math.abs(i) * 4}" r="13" fill="${hair}"/>`;
      return { back: '', front: curls + cap(cy - ry * 0.46) };
    }
    default: return { back: '', front: cap(cy - ry * 0.42) };
  }
}
// ══ Возврат после срыва (DISCIPLINE-BOUNDARIES-PLAN §6 п.4) ══════════════════════════
// Заморозка серии ниже — это ПРОЩЕНИЕ: пропуск не сжигает серию. Но прощение не помогает
// вернуться. Человек, которого не было пять дней, открывает приложение и видит стену
// просроченного — и именно эта стена, а не сломанная серия, решает, что он не вернётся.
// Амнистия — про другое: куча перестаёт висеть, при этом ничего не удаляется. Дела остаются
// в своих днях (`date` не трогаем), просто больше не считаются долгом и не штрафуют.
// Клятвы (`oath`) намеренно НЕ амнистируются: там человек сам поставил ставку, и снимать её
// за него значило бы обесценить механику, которую он выбрал осознанно.
function taskOverdue(x, today) { return !x.done && !!x.date && x.date < (today || todayStr()) && !x.amnesty; }
function amnestyCandidates() { return (State.tasks || []).filter((x) => taskOverdue(x) && !(x.oath && !x.oath.burned)); }
function amnestiedToday() { const d = todayStr(); return (State.tasks || []).filter((x) => x.amnesty === d); }
function currentStreak() {
  const set = new Set(xpEvents().map((e) => e.date));
  let streak = 0, cursor = todayStr(), freezeLeft = (globalPerk('streakShield') || 0) + pathStreakGrace(), guard = 0;
  if (!set.has(cursor)) cursor = addDays(cursor, -1); // сегодня ещё может быть не закрыт — не штрафуем
  while (guard++ < 1000) {
    if (set.has(cursor)) { streak++; cursor = addDays(cursor, -1); }
    else if (freezeLeft > 0) { freezeLeft--; cursor = addDays(cursor, -1); } // 🛡 перк древа: щит серии съедает пропуск
    else break;
  }
  return streak;
}
// Рекорд серии — никогда не сбрасывается (анти-Duolingo: потеря текущей серии не стирает достижение)
function longestStreak() {
  const days = [...new Set(xpEvents().map((e) => e.date))].sort();
  if (!days.length) return 0;
  let best = 1, cur = 1;
  for (let i = 1; i < days.length; i++) { if (addDays(days[i - 1], 1) === days[i]) { cur++; best = Math.max(best, cur); } else cur = 1; }
  return best;
}

// ---- Привычки ----
function habitScheduledOn(h, dateStr) { return (h.days || []).includes(parseDate(dateStr).getDay()); }
function habitDone(h, dateStr) { return !!(State.habitlog[dateStr] && State.habitlog[dateStr][h.id]); }
function todaysHabits() { const t = todayStr(); return State.habits.filter((h) => !h.archived && habitScheduledOn(h, t)); }
function habitsDueOn(dateStr) { return State.habits.filter((h) => !h.archived && habitScheduledOn(h, dateStr)); }
// Щадящий стрик (анти-Duolingo): один пропуск не сжигает серию — «заморозка»
// восстанавливается после каждых 7 отмеченных дней. Жизнь не наказывает за единичный сбой.
function habitStreak(h) {
  const baseFreeze = (currentPath() === 'control') ? 0 : 1; // Контроль строг: серия привычки не прощает пропуск; Доверие/по умолчанию — 1 заморозка
  let s = 0, cursor = todayStr(), guard = 0, freezeLeft = baseFreeze, doneRun = 0;
  if (habitScheduledOn(h, cursor) && !habitDone(h, cursor)) cursor = addDays(cursor, -1); // сегодня ещё не вечер
  while (guard++ < 400) {
    if (!habitScheduledOn(h, cursor)) { cursor = addDays(cursor, -1); continue; }
    if (habitDone(h, cursor)) { s++; doneRun++; if (doneRun >= 7) { freezeLeft = baseFreeze; doneRun = 0; } cursor = addDays(cursor, -1); }
    else if (freezeLeft > 0) { freezeLeft--; doneRun = 0; cursor = addDays(cursor, -1); } // заморозка съедает пропуск
    else break;
  }
  return s;
}

// ---- Цели ----
function goalSkillIds(goal) {
  return uniqueSkillIds(Array.isArray(goal?.skillIds) && goal.skillIds.length ? goal.skillIds : [goal?.skillId], { visibleOnly: false });
}
function goalBackgroundSkillIds(goal) {
  const main = goalSkillIds(goal);
  return uniqueSkillIds(goal?.backgroundSkillIds || [], { visibleOnly: false }).filter((id) => !main.includes(id)).slice(0, LAYER_MAX);
}
// Числовая цель достигнута? (lowerBetter — для оценок/времени, где меньше = лучше)
function goalMetricReached(g) { const m = g.metric; if (!m || m.target == null) return false; return m.lowerBetter ? m.current <= m.target : m.current >= m.target; }
function goalProgressKind(g) { return g.metric && g.metric.target != null ? 'metric' : 'checklist'; }
function goalProgress(g) {
  const m = goalProgressKind(g) === 'metric' ? g.metric : null;
  if (m) {
    const span = m.lowerBetter ? (m.start - m.target) : (m.target - m.start);
    if (!(span > 0)) return goalMetricReached(g) ? 100 : 0;
    const prog = m.lowerBetter ? (m.start - m.current) : (m.current - m.start);
    return Math.max(0, Math.min(100, Math.round(prog / span * 100)));
  }
  const n = g.steps.length; if (!n) return 0; return Math.round(g.steps.filter((s) => s.done).length / n * 100);
}
// Цепочка вверх до Севера (для хлебной крошки «зачем»)
function goalChain(g) { const out = []; let cur = g.parentId ? goalById(g.parentId) : null, guard = 0; while (cur && guard++ < 12) { out.push(cur); cur = cur.parentId ? goalById(cur.parentId) : null; } return out; }
function goalChildren(id, source = State.goals) { return (source || []).filter((goal) => goal.parentId === id); }
function goalDescendantIds(ids, source = State.goals) {
  const result = new Set(ids), queue = [...ids];
  while (queue.length) for (const child of goalChildren(queue.shift(), source)) if (!result.has(child.id)) { result.add(child.id); queue.push(child.id); }
  return result;
}
function goalLinkedTasks(id, source = State.tasks) { return (source || []).filter((task) => task.goalId === id); }
function goalParentOptionsHTML(goal) {
  const blocked = goal ? goalDescendantIds([goal.id]) : new Set();
  return `<option value="">${t('Самостоятельная цель')}</option>` + (State.goals || [])
    .filter((candidate) => !candidate.archived && (!goal || (!blocked.has(candidate.id) && candidate.id !== goal.id)))
    .map((candidate) => `<option value="${candidate.id}" ${goal && goal.parentId === candidate.id ? 'selected' : ''}>${esc(candidate.title)}</option>`).join('');
}
function goalDeepLinkHref(id) {
  const params = new URLSearchParams(location.search); params.set('view', 'goals'); params.set('goal', id);
  return `${location.pathname}?${params.toString()}`;
}
function syncGoalDeepLink(id, view = 'goals') {
  try {
    const params = new URLSearchParams(location.search); params.set('view', view);
    if (id) params.set('goal', id); else params.delete('goal');
    history.replaceState(null, '', `${location.pathname}?${params.toString()}${location.hash}`);
  } catch {}
}
// Статус-бейдж: достигнута / держу / просело / жду / пауза / активна
function goalStatusInfo(g) {
  if (g.completedAt) return { txt: '✅ Достигнута', cls: 'gs-done' };
  if (g.metric && g.metric.maintain && g.metric.everReached) return goalMetricReached(g) ? { txt: '🔄 Держу', cls: 'gs-maint' } : { txt: '⚠️ Просело', cls: 'gs-slip' };
  if (g.status === 'waiting') return { txt: '⏳ Жду' + (g.window ? ' · ' + g.window : ''), cls: 'gs-wait' };
  if (g.status === 'paused') return { txt: '⏸ Пауза', cls: 'gs-pause' };
  return { txt: '▶ Активна', cls: 'gs-active' };
}
// Фаза 2 дерева: цель взята → возможно, это веха на карте пути. Только подсказка-мост,
// не авто-зачёт: веху подтверждает человек (модалка честности), мы лишь напоминаем о ней
// в момент реальной победы — самый честный момент для этого вопроса.
function goalMilestoneHint(g) {
  try {
    const tr = State.tree[g.skillId]; if (!tr) return;
    const next = (tr.nodes || []).find((n) => n.milestone && !n.unlocked && nodeUnlockable(g.skillId, n));
    if (next) { setTimeout(() => { try { toast(`🚩 ${t('Похоже на веху')}: «${next.title}» — ${t('загляни в карту пути')}`); } catch {} }, 1600); track('tree:goal-hint'); }
  } catch {}
}
function announceGoalCompletion(g) {
  toast(`🎯 ${t('Цель достигнута')}: ${g.title} (+${g.xpReward != null ? g.xpReward : GOAL_BONUS.xp} XP)`);
  goalMilestoneHint(g); bossHitFeedback(bossHitCheck('goal', g));
}
function refreshGoalCompletion(g, { announce = true } = {}) {
  if (g.manualComplete && g.completedAt) return;
  if (goalProgressKind(g) === 'metric') {
    const reached = goalMetricReached(g);
    if (reached) g.metric.everReached = true;
    // maintain-цель никогда не «завершается» — остаётся в режиме удержания
    if (reached && !g.metric.maintain && !g.completedAt) { g.completedAt = new Date().toISOString(); if (announce) announceGoalCompletion(g); }
    else if (!reached && g.completedAt && !g.metric.maintain) g.completedAt = null;
    return;
  }
  const allDone = g.steps.length > 0 && g.steps.every((s) => s.done);
  if (allDone && !g.completedAt) { g.completedAt = new Date().toISOString(); if (announce) announceGoalCompletion(g); }
  else if (!allDone && g.completedAt) g.completedAt = null;
}

