  if (choice === 'cosplay') Object.assign(next, { cosplayCharacter: text('cosplayCharacter'), cosplayDate: text('cosplayDate'), cosplayPiece: text('cosplayPiece'), cosplayBudget: data.has('cosplayBudget') });
