// The Guide v3 library is registry-driven. Keep this explicit empty compatibility
// constant so old source-level integrations cannot revive the removed card wall.
const GUIDE_SECTIONS = Object.freeze([]);
function guideV3ReviewPreviewRequested() {
  try {
    const requested = new URLSearchParams(location.search).get('guidePreview') === '1';
    const local = ['localhost', '127.0.0.1', '::1'].includes(location.hostname);
    return requested && (local || State.me?.isAdmin === true);
  }
  catch { return false; }
}
const GUIDE_V3_COPY_RELEASES = Object.freeze({
  ru: Object.freeze({ globalName: 'GuideV3CopyRu', version: '1.4.0', status: 'runtime-approved', released: true }),
  en: Object.freeze({ globalName: 'GuideV3CopyEn', version: '0.5.0', status: 'translated', released: true }),
  de: Object.freeze({ globalName: 'GuideV3CopyDe', version: '0.5.0', status: 'translated', released: true }),
  uk: Object.freeze({ globalName: 'GuideV3CopyUk', version: '0.5.0', status: 'translated', released: true }),
  es: Object.freeze({ globalName: 'GuideV3CopyEs', version: '0.5.0', status: 'translated', released: true }),
});
const GUIDE_V3_CONTEXT_LOCALES = Object.freeze({ ru: '1.4.0', en: '0.5.0', de: '0.5.0', uk: '0.5.0', es: '0.5.0' });
function guideV3ReleasedChapter(completion, registryVersion = 2) {
  return Object.freeze({ registryVersion, completion, released: true, locales: GUIDE_V3_CONTEXT_LOCALES });
}
const GUIDE_V3_CONTEXT_RELEASES = Object.freeze({
  habits: guideV3ReleasedChapter('habit-persisted'),
  calendar: guideV3ReleasedChapter('task-date-persisted'),
  notes: guideV3ReleasedChapter('note-persisted'),
  voice: guideV3ReleasedChapter('voice-choice-persisted'),
  jarvis: guideV3ReleasedChapter('helper-response-seen'),
  systemTheme: guideV3ReleasedChapter('system-theme-persisted'),
  rewards: guideV3ReleasedChapter('purchase-persisted'),
  hero: guideV3ReleasedChapter('hero-seen'),
  den: guideV3ReleasedChapter('den-seen'),
  pets: guideV3ReleasedChapter('pets-seen'),
  tree: guideV3ReleasedChapter('tree-seen', 3),
  stats: guideV3ReleasedChapter('stats-seen'),
});
function guideV3CopyModule(locale = lang()) {
  const code = APP_LANGS.includes(locale) ? locale : null;
  const release = code && GUIDE_V3_COPY_RELEASES[code];
  const copy = release ? window[release.globalName] : null;
  const contractReady = copy && ['format', 'get', 'has', 'entries'].every((method) => typeof copy[method] === 'function');
  return contractReady && copy.LOCALE === code ? copy : null;
}
function guideV3RuntimeAllowed() {
  const locale = lang(), copy = guideV3CopyModule(locale);
  if (!copy) return false;
  if (guideV3ReviewPreviewRequested()) return true;
  // The owner-approved RU table is the source contract. C2 explicitly releases
  // exact versions of its shape-identical translations. New draft files never
  // enter normal runtime merely because they happen to declare `translated`.
  const sourceApproved = window.GuideV3CopyRu?.RUNTIME_APPROVED === true;
  const release = GUIDE_V3_COPY_RELEASES[locale];
  const localeReleased = release?.released === true
    && copy.VERSION === release.version
    && copy.STATUS === release.status
    && (locale !== 'ru' || copy.RUNTIME_APPROVED === true);
  return sourceApproved && localeReleased;
}
function guideV3ContextRuntimeAllowed(chapter, locale = lang()) {
  if (!guideV3RuntimeAllowed()) return false;
  const model = window.GuideV3, copy = guideV3CopyModule(locale), release = GUIDE_V3_CONTEXT_RELEASES[chapter];
  const entry = model?.REGISTRY?.find((item) => item.chapter === chapter);
  return !!(release?.released && copy && entry
    && entry.version === release.registryVersion
    && entry.completion === release.completion
    && copy.VERSION === release.locales?.[locale]
    && copy.CONTEXTUAL_STATUS?.[chapter] === 'runtime-approved');
}
