// ============================================================
//  Вид «Неделя»
// ============================================================
function rangeStats(start, end) {
  const ev = xpEvents().filter((e) => e.date >= start && e.date <= end);
  const xp = ev.reduce((s, e) => s + e.xp, 0), gold = ev.reduce((s, e) => s + e.gold, 0), min = ev.reduce((s, e) => s + e.min, 0);
  const quests = State.tasks.filter((t) => t.done && dayOf(t) >= start && dayOf(t) <= end).length;
  let habitsC = 0; for (const d in State.habitlog) if (d >= start && d <= end) habitsC += Object.keys(State.habitlog[d]).length;
  const byArea = leafSkills().map((s) => ({ label: skillLabel(s.id), value: ev.filter((e) => e.skillId === s.id).reduce((a, e) => a + e.min, 0), color: s.color }));
  return { xp, gold, min, quests, habitsC, byArea };
}
function selectedWeekDate(ws) {
  const start = calendarDateValue(ws, weekStart(todayStr()));
  const end = addDays(start, 6);
  const selected = calendarDateValue(State.calDate, '');
  if (selected && selected >= start && selected <= end) return selected;
  const today = todayStr();
  return today >= start && today <= end ? today : start;
}
function weekTaskRowHTML(task, variant = 'detail') {
  const fullTitle = taskDisplayTitle(task);
  const skill = skillById(task.skillId);
  const timed = calendarTimeValue(task.startTime);
  const draggable = variant === 'board' ? ' draggable="true"' : '';
  return `<div class="wk-task wk-task-${variant}${task.done ? ' done' : ''}"${draggable} data-task="${esc(task.id)}" data-calendar-task="${esc(task.id)}" style="--wk-skill:${esc(skill.color)}">
    <button type="button" class="check wk-task-check" data-action="toggle-task" data-id="${esc(task.id)}" aria-label="${esc(t(task.done ? 'Снять выполнение' : 'Выполнить'))}: ${esc(fullTitle)}" aria-pressed="${task.done ? 'true' : 'false'}">${task.done ? satoruIconHTML('action.check', 'cal-action-icon', '✓') : ''}</button>
    <button type="button" class="wk-task-main" data-action="cal-edit-task" data-id="${esc(task.id)}" aria-label="${esc(t('Открыть расписание квеста'))}: ${esc(fullTitle)}"><span class="wk-task-title" data-noi18n>${taskContentIconHTML(task, 'activity-inline-icon')}${esc(fullTitle)}</span><span class="wk-task-meta"><span>${timed ? esc(timed) : esc(t('Без времени'))}</span><span>${fmtDur(Number(task.estimateMin) || 30)}</span></span></button>
  </div>`;
}
function weekAddAreaHTML(date, variant = 'detail') {
  if (State.wkAddDate !== date) {
    return `<button type="button" class="btn ghost wk-add-btn" data-action="wk-add-task" data-date="${date}" aria-label="${esc(t('Добавить квест на этот день'))}">${satoruIconHTML('action.add', 'button-glyph', '+')} ${esc(t('Добавить квест'))}</button>`;
  }
  return `<form class="wk-add-form wk-add-form-${variant}" data-date="${date}">
    <label><span>${esc(t('Название квеста'))}</span><input name="title" maxlength="160" autocomplete="off" required /></label>
    <label><span>${esc(t('Сфера'))}</span><select name="skillId">${skillOptionsHTML()}</select></label>
    <p class="wk-add-status muted" aria-live="polite"></p>
    <div class="wk-add-btns"><button type="submit" class="btn">${esc(t('Добавить квест'))}</button><button type="button" class="btn ghost" data-action="wk-add-cancel" data-date="${date}" aria-label="${esc(t('Отменить добавление'))}">${esc(t('Отмена'))}</button></div>
  </form>`;
}
function renderWeekly() {
  if (State._tasksLoadError) return calendarLoadRecoveryHTML();
  State.calMode = 'week';
  const ws = State.weekStart || (State.weekStart = weekStart(State.calDate || todayStr()));
  const end = addDays(ws, 6), st = rangeStats(ws, end);
  const wk = State.weeks[ws] || { intention: '', review: '' };
  const isThis = ws === weekStart(todayStr());
  const today = todayStr();
  const WD_BY_JS = ['Вс', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб'];
  const selected = selectedWeekDate(ws);
  State.calDate = selected;
  const dayData = Array.from({ length: 7 }, (_, i) => {
    const d = addDays(ws, i);
    const tasks = State.tasks.filter((task) => task.date === d).sort((a, b) => {
      const at = calendarTimeValue(a.startTime), bt = calendarTimeValue(b.startTime);
      if (at && bt) return at.localeCompare(bt) || String(a.createdAt || '').localeCompare(String(b.createdAt || ''));
      if (at) return -1;
      if (bt) return 1;
      return String(a.createdAt || '').localeCompare(String(b.createdAt || ''));
    });
    return { date: d, tasks, open: tasks.filter((task) => !task.done).length, done: tasks.filter((task) => task.done).length, planned: tasks.reduce((sum, task) => sum + (Number(task.estimateMin) || 0), 0), habits: habitsDueOn(d) };
  });
  const strip = dayData.map((day) => {
    const active = day.date === selected, isToday = day.date === today;
    const weekday = t(WD_BY_JS[parseDate(day.date).getDay()]);
    const summary = `${weekday} ${Number(day.date.slice(8))} · ${t('Квестов на день')}: ${day.tasks.length} · ${t('Запланировано времени на день')}: ${fmtDur(day.planned)}`;
    return `<button type="button" class="calv-day week-overview-day${active ? ' active' : ''}${isToday ? ' is-today' : ''}" data-action="cal-date" data-date="${day.date}" aria-label="${esc(summary)}" aria-pressed="${active ? 'true' : 'false'}" ${isToday ? 'aria-current="date"' : ''}><span class="cd-wd">${esc(weekday)}</span><span class="cd-n">${Number(day.date.slice(8))}</span><span class="cd-dot${day.open ? '' : '-empty'}" ${day.open ? `aria-label="${day.open}"` : 'aria-hidden="true"'}>${day.open || ''}</span></button>`;
  }).join('');
  const board = dayData.map((day) => {
    const isToday = day.date === today;
    const taskRows = day.tasks.map((task) => weekTaskRowHTML(task, 'board')).join('');
    const habitDots = day.habits.length ? `<div class="wk-habits-dots" aria-label="${esc(t('Привычек'))}: ${day.habits.length}">${day.habits.map((habit) => `<span class="wk-h-dot${habitDone(habit, day.date) ? ' done' : ''}" style="--c:${esc(skillById(habit.skillId).color)}" title="${esc(habit.title)}" aria-hidden="true"></span>`).join('')}</div>` : '';
    return `<section class="wk-col${isToday ? ' is-today' : ''}" data-date="${day.date}" aria-label="${esc(t(WD_BY_JS[parseDate(day.date).getDay()]))} ${Number(day.date.slice(8))}"><header class="wk-col-head"><span class="wk-wd">${esc(t(WD_BY_JS[parseDate(day.date).getDay()]))}</span><span class="wk-date">${dmShort(day.date)}</span><span class="wk-prog">${day.done}/${day.tasks.length}</span></header><div class="wk-load" title="${esc(t('Запланировано времени на день'))}">${fmtDur(day.planned)}</div><div class="wk-tasks">${taskRows || `<p class="wk-empty muted">${esc(t('Пусто'))}</p>`}</div>${habitDots}${weekAddAreaHTML(day.date, 'board')}</section>`;
  }).join('');
  const selectedDay = dayData.find((day) => day.date === selected) || dayData[0];
  const selectedWeekday = t(WD_BY_JS[parseDate(selectedDay.date).getDay()]);
  const detailRows = selectedDay.tasks.map((task) => weekTaskRowHTML(task, 'detail')).join('');

  const reflections = Object.entries(State.days)
    .filter(([d, v]) => d >= ws && d <= end && v.reflection && v.reflection.trim())
    .sort((a, b) => (a[0] < b[0] ? 1 : -1))
    .map(([d, v]) => `<li><span class="date">${d}</span><br>${esc(v.reflection)}</li>`)
    .join('');

  return `
  <section class="calendar-shell calendar-week-shell" aria-labelledby="calendar-screen-title">
    <header class="card calv-head"><div class="calv-title"><div class="calv-title-main"><button type="button" class="btn ghost sm cal-nav-prev" data-action="week-prev" aria-label="${esc(t('Предыдущая неделя'))}">${satoruIconHTML('action.back', 'cal-action-icon', '‹')}</button><h2 id="calendar-screen-title" class="week-screen-title" tabindex="-1">${esc(t('Неделя'))} ${dmShort(ws)} – ${dmShort(end)}${isThis ? ` <span class="muted">· ${esc(t('(текущая)'))}</span>` : ''}</h2><button type="button" class="btn ghost sm cal-nav-next" data-action="week-next" aria-label="${esc(t('Следующая неделя'))}">${satoruIconHTML('action.forward', 'cal-action-icon', '›')}</button></div>${calModeToggle('week')}${calendarToolsHTML()}</div><div class="calv-strip week-overview" role="group" aria-label="${esc(t('Дни выбранной недели'))}">${strip}</div></header>
    ${calendarMoveReceiptHTML()}
    <main class="week-work"><section class="card week-work-card" aria-labelledby="week-work-title"><div class="week-work-head"><div><h3 id="week-work-title"><span class="week-work-title-desktop">${esc(t('Квесты недели'))}</span><span class="week-work-title-mobile">${esc(t('Квесты выбранного дня'))}</span></h3><span class="muted week-selected-summary">${esc(selectedWeekday)} ${dmShort(selectedDay.date)} · ${selectedDay.tasks.length} · ${fmtDur(selectedDay.planned)}</span></div></div><div class="wk-mobile-detail" role="region" aria-label="${esc(t('Выбранный день'))}"><div class="wk-detail-tasks">${detailRows || `<div class="wk-detail-empty"><p>${esc(t('Нет квестов на этот день'))}</p></div>`}</div>${weekAddAreaHTML(selectedDay.date, 'detail')}</div><div class="wk-grid-wrap"><div class="wk-grid">${board}</div></div><p class="wk-hint muted">${esc(t('На desktop можно перетащить квест в другой день; тап, клик или Enter открывает расписание.'))}</p></section></main>
    <aside class="week-secondary"><div class="card week-summary-card"><div class="week-summary-head"><h3>${esc(t('Итоги недели'))}</h3><button type="button" class="btn ghost" data-action="share-week" aria-label="${esc(t('Поделиться итогами недели'))}">${satoruIconHTML('action.share', 'button-glyph', '📤')} ${esc(t('Поделиться'))}</button></div><div class="kpis"><div class="kpi"><div class="v">${st.xp}</div><div class="l">${t('XP за неделю')}</div></div><div class="kpi"><div class="v">🪙 ${st.gold}</div><div class="l">${t('Золото')}</div></div><div class="kpi"><div class="v">${st.quests}</div><div class="l">${t('Квестов')}</div></div><div class="kpi"><div class="v">${st.habitsC}</div><div class="l">${t('Привычек')}</div></div><div class="kpi"><div class="v">${fmtDur(st.min)}</div><div class="l">${t('Времени')}</div></div></div></div>
    <div class="card week-chart-card"><h3>📊 ${t('Время по сферам')}</h3>${barChartSVG(st.byArea)}</div>
    <div class="card week-review-card"><h3>🎯 ${t('Намерение на неделю')}</h3>
      <textarea id="week-intention" placeholder="${esc(t('Что главное на этой неделе? Куда направить фокус…'))}">${esc(wk.intention || '')}</textarea>
      <h3 style="margin-top:14px">🔄 ${t('Итоги недели')}</h3>
      <textarea id="week-review" placeholder="${esc(t('Что получилось, что нет, что перенести…'))}">${esc(wk.review || '')}</textarea>
      <div style="margin-top:10px"><button class="btn" data-action="save-week">${t('Сохранить')}</button>
    </div></div>
    ${reflections ? `<div class="card week-reflections-card"><h3>${t('Рефлексии этой недели')}</h3><ul class="reflections">${reflections}</ul></div>` : ''}</aside>
  </section>`;
}

// ============================================================
//  Вид «Статистика»
// ============================================================
function xpByDay(n) {
  const ev = xpEvents(), out = [];
  for (let i = n - 1; i >= 0; i--) { const d = addDays(todayStr(), -i); out.push({ label: dmShort(d), value: ev.filter((e) => e.date === d).reduce((s, e) => s + e.xp, 0) }); }
  return out;
}
function weekStart(s) { const wd = (parseDate(s).getDay() + 6) % 7; return addDays(s, -wd); }
function timeByAreaThisWeek() { const ws = weekStart(todayStr()); return rangeStats(ws, addDays(ws, 6)).byArea; }
// chart-labels-v1: подписи столбцов не слипаются (fb_ms4m1ur2m1ip). Даты можно
// прореживать (пропуск восстанавливается по соседям), имена сфер — никогда
// (столбец без подписи никто не опознает) — решает вызывающий через opts.thinnable,
// сама функция не выбирает, потому что не знает, что именно подписано.
function barChartSVG(data, opts) {
  const o = opts || {};
  const w = 600, h = 190, pad = 26, bw = (w - pad * 2) / Math.max(1, data.length), max = Math.max(1, ...data.map((d) => d.value));
  const L = window.ChartLabelsV1;
  const layout = L ? L.layout({ labels: data.map((d) => d.label), width: w, pad, fontSize: 9, thinnable: !!o.thinnable })
    : { mode: 'horizontal', angle: 0, every: 1, maxChars: null };
  const bars = data.map((d, i) => {
    const bh = Math.round((d.value / max) * (h - pad * 2)), x = pad + i * bw + bw * 0.15, y = h - pad - bh, ww = bw * 0.7, color = d.color || 'var(--accent)';
    let lbl = '';
    if (i % layout.every === 0) {
      const text = layout.mode === 'truncated' && L ? L.clip(d.label, layout.maxChars) : d.label;
      const cx = x + ww / 2, cy = h - pad + 14;
      const rotate = layout.angle ? ` transform="rotate(${layout.angle} ${cx} ${cy})"` : '';
      lbl = `<text class="bar-lbl" x="${cx}" y="${cy}" text-anchor="${layout.angle ? 'end' : 'middle'}"${rotate}>${esc(text)}</text>`;
    }
    return `<rect x="${x}" y="${y}" width="${ww}" height="${bh}" rx="3" fill="${color}"></rect>${d.value ? `<text class="bar-val" x="${x + ww / 2}" y="${y - 4}" text-anchor="middle">${d.value}</text>` : ''}${lbl}`;
  }).join('');
  return `<svg viewBox="0 0 ${w} ${h}" class="chart" preserveAspectRatio="xMidYMid meet">${bars}</svg>`;
}
function renderStats() {
  ensureAiKeys();
  const since = addDays(todayStr(), -13);
  const planned14 = (State.tasks || []).filter((t) => t.date >= since && t.date <= todayStr());
  const rate = planned14.length ? Math.round((planned14.filter((t) => t.done).length / planned14.length) * 100) : null;
  const reflections = Object.entries(State.days || {}).filter(([, v]) => v && v.reflection && v.reflection.trim()).sort((a, b) => (a[0] < b[0] ? 1 : -1)).slice(0, 7).map(([d, v]) => `<li><span class="date">${d}</span><br>${esc(v.reflection)}</li>`).join('');
  const cr = charRank(), bal = balanceIndex();
  const hasBalanceSignal = bal.active >= 2 && bal.windowMin > 0;
  const balColor = !hasBalanceSignal ? 'var(--muted)' : (bal.index >= 70 ? '#5fbf7a' : bal.index >= 40 ? '#e0a23e' : '#e0526a');
  const rankRow = (s, sub) => {
    const lvl = skillLevelOf(s.id), r = rankFor(lvl), rp = rankProgress(lvl);
    return `<div class="rank-row ${sub ? 'sub' : ''}">
      <span class="rr-dot" style="background:${esc(s.color)}"></span>
      <span class="rr-name">${sub ? '↳ ' : ''}${esc(s.name)}</span>
      <span class="rr-rank" style="--rc:${r.color}">${rankIconHTML(r, 'rank-inline-icon')} ${r.name}</span>
      <span class="rr-lvl">ур.${lvl}</span>
      <span class="rr-bar"><span style="width:${rp.pct}%;background:${r.color}"></span></span>
      <span class="rr-next muted">${rp.next ? `+${rp.toNext} до «${rp.next.name}»` : 'макс'}</span></div>`;
  };
  const skillRanksRows = topSkills().map((s) => rankRow(s, false) + childSkills(s.id).map((c) => rankRow(c, true)).join('')).join('');
  const advanced = isPro()
    ? `<div class="card"><h3>${t('Время по сферам')}</h3>${barChartSVG(timeByAreaThisWeek())}</div>`
    : `<section class="card locked-card"><button type="button" class="lock-veil" data-action="show-paywall" data-feature="Расширенная аналитика"><span>${satoruIconHTML('status.lock', 'inline-glyph', '◇')} ${t('Расширенная аналитика')} — Pro</span></button>
        <h3>${t('Время по сферам')}</h3>${barChartSVG(timeByAreaThisWeek())}</section>`;
  // Эпизоды: без списка сохранённый период исчезал из виду, а ошибка ИИ в разборе оставалась
  // навсегда неверным опытом — откатить было нечем. Здесь же вход «записать эпизод» вручную,
  // не дожидаясь нуджа (поездку можно отметить сразу, а не после недели тишины).
  // Нагрузка сфер: превышение сферой СВОЕЙ нормы за 7 дней против личной базы за 28.
  // Тумблер «восстанавливает» стоит прямо здесь, а не в Настройках: он нужен ровно в тот момент,
  // когда видишь «перегрев отдыха» и понимаешь, что для этой сферы предупреждение бессмысленно.
  const loads = sphereLoads().filter((r) => r.ratio != null || r.rec > 0);
  const ins = loadInsight();
  const loadCard = loads.length ? `<div class="card"><h3>🌡 ${t('Нагрузка сфер')}</h3>
    <p class="muted" style="font-size:12.5px;margin:0 0 10px">${t('Сравнение с твоей же нормой: последние 7 дней против предыдущих 28. Не «много вообще», а «много для тебя».')}</p>
    ${ins ? `<p class="load-insight">${t('Перегрев')}: <b>${esc(ins.hot.name)}</b> — ×${ins.hot.ratio.toFixed(1)} ${t('от твоей нормы')}${ins.quiet.length ? `. ${t('Без внимания')}: ${ins.quiet.map((q) => esc(q.name)).join(', ')}` : ''}.</p>` : ''}
    <div class="load-rows">${loads.map((r) => {
      const pct = r.ratio == null ? null : Math.max(4, Math.min(100, Math.round(r.ratio / 3 * 100)));
      return `<div class="load-row">
        <span class="load-name">${esc(r.name)}</span>
        <span class="load-bar">${pct == null ? `<i class="load-none"></i>` : `<i style="width:${pct}%;background:${r.hot ? '#e0526a' : esc(r.color)}"></i>`}</span>
        <span class="load-val ${r.hot ? 'is-hot' : ''}">${r.ratio == null ? t('мало данных') : '×' + r.ratio.toFixed(1)}</span>
        <button type="button" class="load-restore${r.restores ? ' on' : ''}" data-action="toggle-restores" data-id="${r.id}" aria-pressed="${r.restores ? 'true' : 'false'}" aria-label="${esc(t('Эта сфера меня восстанавливает — не предупреждать о перегрузе'))}: ${esc(r.name)}">${r.restores ? '🌿' : '·'}</button>
      </div>`;
    }).join('')}</div>
    <p class="muted" style="font-size:11.5px;margin:8px 0 0">🌿 — ${t('сфера восстанавливает: перегрев по ней не считается')}</p></div>` : '';
  const epList = (State.episodes || []).slice().sort((a, b) => (a.from < b.from ? 1 : -1));
  const episodesCard = `<div class="card"><h3>🎒 ${t('Эпизоды')}</h3>
    <p class="muted" style="font-size:12.5px;margin:0 0 10px">${t('Периоды, когда жизнь шла, а записывать было некогда: поездки, интенсивы, болезнь.')}</p>
    ${epList.length ? `<div class="ep-cards">${epList.map((ep) => {
      const d = episodeDays(ep).length, xp = episodeTotalXp(ep);
      const top = (ep.profile || []).slice().sort((a, b) => b.intensity - a.intensity).slice(0, 3)
        .map((p) => `${esc(skillLabel(p.skillId))} <span class="muted">${t(EPISODE_INTENSITY[p.intensity])}</span>`).join(' · ');
      return `<div class="ep-card">
        <div class="ep-card-head">
          <span class="ep-card-title">${episodeType(ep.type).icon} ${esc(ep.title)}</span>
          <button type="button" class="del" data-action="ep-del" data-id="${ep.id}" aria-label="${esc(t('Удалить эпизод'))}: ${esc(ep.title)}">✕</button>
        </div>
        <div class="ep-card-meta">${dmShort(ep.from)} — ${dmShort(ep.to)} · ${d} ${plural(d, 'день', 'дня', 'дней')} · +${xp} XP</div>
        <div class="ep-card-top">${top}</div>
      </div>`;
    }).join('')}</div>` : `<p class="muted" style="font-size:12.5px">${t('Пока пусто.')}</p>`}
    <div class="propose-actions"><button class="btn ghost" data-action="episode-open">🎒 ${t('Записать эпизод')}</button></div></div>`;
  const balanceSummary = hasBalanceSignal
    ? (bal.weakest && bal.index < 80 ? `${t('Без внимания')}: ${esc(bal.weakest.name)}` : t('Ритм сфер устойчив'))
    : t('Баланс появится, когда хотя бы две сферы получат внимание. Это не оценка тебя.');
  return `<section class="stats-shell" data-guide-target="stats-overview" aria-labelledby="stats-title">
    <header class="stats-route-head"><h2 id="stats-title" tabindex="-1">${satoruIconHTML('nav.progress', 'heading-glyph', '◇')} ${t('Прогресс')}</h2></header>
    <section class="card stats-lead weekly-insight" aria-labelledby="stats-week-title"><div><span class="th-kicker">${t('Последние 14 дней')}</span><h3 id="stats-week-title">${rate == null ? t('Пока нет планов') : `${rate}% · ${t('Выполнение (14 дн.)')}`}</h3><p class="muted">${balanceSummary}</p></div><div class="stats-lead-actions"><button class="btn" data-action="ai-review">${t('Разобрать неделю')}</button><button class="btn ghost" data-action="share-week">${satoruIconHTML('action.export', 'button-glyph', '◇')} ${t('Твоя неделя')}</button></div></section>
    <div class="kpis stats-kpis-compact">
      <div class="kpi"><div class="v">${rankIconHTML(cr, 'kpi-emblem')} ${charLevel()}</div><div class="l">${cr.name}</div></div>
      <div class="kpi"><div class="v" style="color:${balColor}">${hasBalanceSignal ? bal.index : '—'}</div><div class="l">${hasBalanceSignal ? t('Индекс баланса') : t('Наблюдаем баланс')}</div></div>
      <div class="kpi"><div class="v">${satoruIconHTML('status.streak', 'kpi-emblem', '◇')} ${currentStreak()}</div><div class="l">${t('Серия')} · ${longestStreak()}</div></div>
      <div class="kpi"><div class="v">${overallXp()}</div><div class="l">${t('Всего опыта')}</div></div>
    </div>
    <details class="card stats-progressive"><summary>${t('Ритм и баланс')}</summary><div class="stats-progressive-body">
      <div class="balance-card${hasBalanceSignal ? '' : ' is-observing'}"><div class="bal-head"><h3>⚖️ ${t('Баланс сфер')}</h3><div class="bal-score" style="color:${balColor}">${hasBalanceSignal ? `${bal.index}<small>/100</small>` : '—'}</div></div>${hasBalanceSignal ? `<div class="bal-meter" aria-hidden="true"><span style="width:${bal.index}%;background:${balColor}"></span></div>` : ''}<p class="muted">${balanceSummary}</p></div>
      <section><h3>${t('Ранги по сферам')}</h3>${skillRanksRows || `<p class="muted">${t('Добавь навыки в Настройках.')}</p>`}</section>
      <section><h3>${t('XP по дням')}</h3>${barChartSVG(xpByDay(14), { thinnable: true })}</section>
      ${advanced}${loadCard}
    </div></details>
    <details class="card stats-progressive"><summary>${t('История и контекст')}</summary><div class="stats-progressive-body">${episodesCard}<section><h3>${t('Рефлексии этой недели')}</h3>${reflections ? `<ul class="reflections">${reflections}</ul>` : `<p class="muted">${t('Пока нет записей.')}</p>`}</section></div></details>
    <details class="card stats-progressive"><summary>${t('Все показатели')}</summary><div class="stats-inline-metrics"><span>${satoruIconHTML('status.gold', 'inline-emblem', '◇')} ${goldBalance()} · ${t('Золото')}</span><span>${overallXp()} · ${t('Всего опыта')}</span><span>${t('Серия')} ${currentStreak()} · ${t('рекорд')} ${longestStreak()}</span></div></details>
  </section>`;
}

// ============================================================
//  Вид «Настройки»
