    if (['yes', 'no'].includes(row.boundaryHeld)) { boundaryHeld[row.boundaryHeld] += 1; boundaryHeld.known += 1; }
    if (['better', 'same', 'worse'].includes(row.afterEffect)) { effects[row.afterEffect] += 1; effects.known += 1; }
