const ACCENTS = ['#6c8cff', '#22c1a4', '#e0526a', '#b06ff0', '#e0a23e', '#4f9ff7']; // палитра акцентов (#тема)
function applyTheme() {
  const s = State.settings || {};
  document.documentElement.lang = lang();
  // Путь «Контроль» авто-надевает скин «Система» (Solo-Leveling-эстетика строгости), если юзер явно не отключил его оверрайдом.
  const controlSkin = s.path === 'control' && !s.systemSkinOff;
  const sys = !!s.systemMode || controlSkin;
  const deviceTheme = (() => { try { return window.matchMedia?.('(prefers-color-scheme: light)').matches ? 'light' : 'dark'; } catch { return 'dark'; } })();
  document.documentElement.dataset.theme = sys ? 'dark' : (s.theme === 'system' ? deviceTheme : (s.theme === 'light' ? 'light' : 'dark'));
  document.documentElement.dataset.system = sys ? 'on' : 'off';
  document.documentElement.dataset.path = s.path === 'control' ? 'control' : 'trust';
  document.documentElement.style.setProperty('--accent', sys ? '#4fd6ff' : (s.accent || '#6c8cff'));
}
let _systemThemeMedia = null;
function initSystemThemeListener() {
  try {
    _systemThemeMedia = window.matchMedia('(prefers-color-scheme: light)');
    const repaint = () => { if (State.settings?.theme === 'system') applyTheme(); };
    if (typeof _systemThemeMedia.addEventListener === 'function') _systemThemeMedia.addEventListener('change', repaint);
    else if (typeof _systemThemeMedia.addListener === 'function') _systemThemeMedia.addListener(repaint);
  } catch { _systemThemeMedia = null; }
}
let _themeChoiceBusy = false;
async function persistThemeChoice(rawChoice) {
  if (_themeChoiceBusy) return false;
  if (!['dark', 'light', 'system'].includes(rawChoice)) return false;
  const choice = rawChoice;
  _themeChoiceBusy = true;
  let guideResult = null;
  const completeGuide = choice === 'system' && guideV3ContextActive('systemTheme', 'system-theme-persisted');
  const saved = await guideV3Exclusive(async ({ epoch, accountId }) => Store.updateNow('settings', (current) => {
    if (!current || epoch !== _guideV3WriteEpoch || accountId !== String(State.me?.id || '')) return undefined;
    const next = structuredClone(current);
    next.theme = choice;
    next.systemMode = false;
    if (next.path === 'control') next.systemSkinOff = true;
    if (completeGuide) {
      guideResult = window.GuideV3?.reduce(current.guideV3, {
        type: 'guide:context-complete', completion: 'system-theme-persisted', persisted: true, at: Date.now(),
      }) || null;
      if (!guideResult?.accepted) return undefined;
      next.guideV3 = guideResult.state;
    }
    return next;
  }, (committed) => {
    if (epoch !== _guideV3WriteEpoch || accountId !== String(State.me?.id || '')) return false;
    State.settings = committed;
    return true;
  }));
  _themeChoiceBusy = false;
  if (!saved) {
    if (completeGuide) State._guideV3Error = 'persist';
    applyTheme(); render();
    return false;
  }
  State._guideV3Error = '';
  if (guideResult?.metric) track(guideResult.metric);
  applyTheme(); render();
  return true;
}
// Авто-репорт креша на сервер (раз на ключ за сессию) — чтобы видеть прод-падения в фидбеке.
function reportCrash(view, e) {
  try {
    State._reportedErrors = State._reportedErrors || new Set();
    const key = view + ':' + ((e && e.message) || e);
    if (State._reportedErrors.has(key)) return; State._reportedErrors.add(key);
    fetch('/api/feedback', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind: 'bug', text: `[авто-креш] раздел «${view}»: ` + String((e && e.stack) || e).slice(0, 900), attachments: [] }) }).catch(() => {});
  } catch {}
}
function viewErrorCard(view, e) {
  const admin = State.me && State.me.isAdmin;
  return `<div class="card err-card">
    <h3>😔 Этот раздел не открылся</h3>
    <p class="muted">Сбой в разделе «${esc(view)}», но твои данные целы. Вернись на «Сегодня» или обнови страницу — отчёт уже ушёл нам.</p>
    <div class="err-acts"><button class="btn" data-action="goto-today">← На сегодня</button><button class="btn ghost" data-action="reload-app">↻ Обновить</button></div>
    ${admin ? `<pre class="err-trace">${esc(String((e && e.stack) || e)).slice(0, 700)}</pre>` : ''}
  </div>`;
}
// Гарантирует, что core-поля состояния — нужного типа (массив/объект), а не null/мусор.
// Корневая защита от краша вида (Календарь/Статистика у Виолы): любой хелпер итерирует безопасно.
function normalizeCoreState() {
  for (const k of ['tasks', 'habits', 'goals', 'purchases', 'rewards', 'inbox', 'antihabits']) if (!Array.isArray(State[k])) State[k] = [];
  for (const k of ['days', 'habitlog', 'tree', 'achievements', 'weeks']) if (!State[k] || typeof State[k] !== 'object' || Array.isArray(State[k])) State[k] = {};
}
function ensureShadowFabRig() {
  if (!window.ShadowRig || !State.settings) return;
  const fab = document.getElementById('ai-fab'); if (!fab) return;
  const c = ensureCompanion(), tier = compTierIdx(c.bond);
  let rig = fab.querySelector('[data-shadow-rig]');
  if (!rig || Number(rig.dataset.shadowTier) !== tier) {
    if (rig) rig.remove();
    const legacy = fab.querySelector('.fab-face'); if (legacy) legacy.remove();
    const streak = fab.querySelector('.fab-streak');
    if (streak) streak.insertAdjacentHTML('beforebegin', window.ShadowRig.markup({ tier, state: State._chatBusy ? 'thinking' : 'listening', context: 'fab', label: c.name || 'Тень' }));
    rig = fab.querySelector('[data-shadow-rig]');
  }
  window.ShadowRig.setState(rig, State._chatBusy ? 'thinking' : 'listening');
}

let _renderedMainView = '';
let _mainRenderToken = 0;
function safeViewMarkup(view) {
  // Ошибка tasks — глобальное состояние приложения, а не «пустой Calendar».
  // Пока исходный файл не прочитан и не проверен, ни один task-dependent
  // экран не получает fallback-массив и не предлагает мутирующие controls.
  if (State._tasksLoadError) return calendarLoadRecoveryHTML();
  try {
    return (VIEWS[view] || renderToday)();
  } catch (e) {
    console.error('Сбой рендера раздела:', view, e);
    reportCrash(view, e);
    try { return viewErrorCard(view, e); } catch { return '<div class="card"><p>Ошибка. Обнови страницу.</p></div>'; }
  }
}
function waitForViewImages(root, maxWait = 650) {
  const images = Array.from(root.querySelectorAll('img')).filter((img) => img.loading !== 'lazy');
  if (!images.length) return Promise.resolve();
  const jobs = images.map((img) => {
    if (img.complete && img.naturalWidth > 0) {
      return typeof img.decode === 'function' ? img.decode().catch(() => {}) : Promise.resolve();
    }
    return new Promise((resolve) => {
      const done = () => resolve();
      img.addEventListener('load', done, { once: true });
      img.addEventListener('error', done, { once: true });
    }).then(() => (typeof img.decode === 'function' ? img.decode().catch(() => {}) : undefined));
  });
  return Promise.race([
    Promise.all(jobs),
    new Promise((resolve) => setTimeout(resolve, maxWait)),
  ]);
}
